          "interest_after": "17470.22",
          "expenses_after": "0.00",
          "allocation": "26952元全部抵本金，此前127日利息留存。"
        },
        {
          "transaction": "T-03",
          "principal_after": "186706.20",
          "interest_after": "9823.63",
          "expenses_after": "0.00",
          "allocation": "28683元不足清偿累计合法利息，不抵本金。"
        },
        {
          "transaction": "T-04",
          "principal_after": "186706.20",
          "interest_after": "4136.69",
          "expenses_after": "0.00",
