          "principal_after": "172130.51",
          "interest_after": "0.00",
          "expenses_after": "0.00",
          "allocation": "32145元先清累计利息，余款抵本金。"
        },
        {
          "transaction": "T-06",
          "principal_after": "164064.65",
          "interest_after": "0.00",
          "expenses_after": "0.00",
          "allocation": "33876元先清421日利息，余款抵本金。"
